<script setup>import {reactive} from 'vue';import {router} from '@inertiajs/vue3';import Layout from './Layout.vue';defineProps({zones:Array});const form=reactive({name:'',fee:'',is_active:true});function create(){router.post('/admin/delivery',form,{onSuccess:()=>Object.assign(form,{name:'',fee:'',is_active:true})})}function toggle(z){router.patch('/admin/delivery/'+z.id,{name:z.name,fee:z.fee,is_active:!z.is_active},{preserveScroll:true});}</script>
<template><Layout><p class="eyebrow">Operations</p><h1 class="serif text-5xl font-bold">Delivery zones</h1><div class="card mt-6"><div class="grid gap-3 sm:grid-cols-2"><input v-model="form.name" class="field" placeholder="Area / zone"><input v-model="form.fee" class="field" placeholder="Delivery fee"></div><button @click="create" class="pill dark mt-4">Add zone</button></div><div class="mt-5 grid gap-3"><article v-for="z in zones" :key="z.id" class="card flex items-center justify-between"><div><h2 class="serif text-2xl font-bold">{{z.name}}</h2><p class="text-sm opacity-60">{{z.is_active?'Available':'Hidden'}}</p></div><div class="flex items-center gap-3"><b>{{z.fee}} EGP</b><button @click="toggle(z)" class="pill">{{z.is_active?'Active':'Hidden'}}</button></div></article></div></Layout></template>
